import React from "react";

export default function HexagonPulseBackground() {
  // create a simple hexagon path and tile it in a grid
  const cols = 16;
  const rows = 10;
  const hexW = 90; // approximate width
  const hexH = 78; // approximate height

  const hexagons = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = c * (hexW * 0.75);
      const y = r * hexH + (c % 2 ? hexH / 2 : 0);
      const opacity = 0.06 + ((r + c) % 3) * 0.02;
      const delay = ((r + c) % 6) * 0.15;
      hexagons.push({ x, y, opacity, delay });
    }
  }

  return (
    <div className="absolute inset-0 w-full h-full overflow-hidden pointer-events-none">
      <svg className="w-full h-full" viewBox={`0 0 ${cols * hexW} ${rows * hexH}`} xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid slice" aria-hidden>
        <defs>
          <polygon id="hex" points="30,15 45,25 45,45 30,55 15,45 15,25" />
        </defs>

        {hexagons.map((h, i) => (
          <use
            key={i}
            href="#hex"
            x={h.x}
            y={h.y}
            fill="#06b6d4"
            fillOpacity={h.opacity}
            className="hex-pulse"
            style={{ animationDelay: `${h.delay}s` }}
          />
        ))}
      </svg>
      <style>{`
        @keyframes pulseHex {
          0%,100% { opacity: 0.06; transform: scale(1); }
          50% { opacity: 0.22; transform: scale(1.06); }
        }
        .hex-pulse { transform-box: fill-box; transform-origin: center; animation: pulseHex 3s ease-in-out infinite; }
      `}</style>
    </div>
  );
}
